    assert "PERSISTED_ADMISSION_COMPACTED_PAYLOAD_MUTATED" in reasons
    assert valid == []
    assert len(quarantined) == 1
    assert quarantined[0]["counts_as_economic_evidence"] is False
    assert quarantined[0]["trainer_consumable"] is False


