def _execution_microstructure_test_market(
    evidence: dict[str, object] | None,
) -> dict[str, object]:
    _intent, market = _complete_runtime_cost_capture_intent_and_microstructure(
        microstructure_action="ALLOW",
        microstructure_trust_score=0.82,
    )
    for field in paper_loop._MICROSTRUCTURE_ALLOCATION_ACTIVE_FIELDS:  # noqa: SLF001
        market.pop(field, None)
    if evidence is not None:
        market.update(deepcopy(evidence))
    return market


def _assert_microstructure_receipt_hash(receipt: dict[str, object]) -> None:
    receipt_material = deepcopy(receipt)
    receipt_sha256 = receipt_material.pop("receipt_sha256")
    assert receipt_sha256 == paper_loop._paper_canonical_sha256(  # noqa: SLF001
        receipt_material
    )


def test_execution_microstructure_reader_uses_authenticated_trust_contract(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    calls: list[dict[str, object]] = []
    expected = _execution_microstructure_test_evidence()

    def fake_read(
        redis_client: object,
        symbol: str,
        *,
        decision_time: object,
        timeframe: str,
        capture_consumer_decision_after_read: bool,
    ) -> dict[str, object]:
        calls.append(
            {
                "redis_client": redis_client,
                "symbol": symbol,
                "decision_time": decision_time,
                "timeframe": timeframe,
                "capture_consumer_decision_after_read": (
                    capture_consumer_decision_after_read
                ),
            }
        )
        return expected

    monkeypatch.setattr(paper_loop, "_read_v2_microstructure_trust", fake_read)
    redis_client = object()

    actual = paper_loop._read_execution_microstructure_trust(  # noqa: SLF001
        redis_client,
        symbol="bankusdt",
        timeframe="15m",
    )

    assert actual is expected
    assert calls == [
        {
            "redis_client": redis_client,
            "symbol": "bankusdt",
            "decision_time": None,
            "timeframe": "15m",
            "capture_consumer_decision_after_read": True,
        }
    ]


