    assert "MISSING_EXPLICIT_FEE_BPS_AT_DECISION_TIME" in reasons
    assert "MISSING_EXPLICIT_FUNDING_BPS_AT_DECISION_TIME" in reasons
    assert "MISSING_MARKET_DEPTH_EVIDENCE" in reasons


