def _reused_candidate_position(*, side: str, identity: str) -> dict[str, object]:
    return {
        "position_id": f"paper_pos_{identity}_{side}",
        "position_generation_id": f"position_generation_{identity}_{side}",
        "entry_fill_id": f"fill_{identity}_{side}",
        "source_fill_ids": [f"fill_{identity}_{side}"],
        "prediction_id": f"prediction_{identity}_{side}",
        "signal_id": f"signal_{identity}_{side}",
        "intent_id": f"intent_{identity}_{side}",
        "risk_decision_id": f"risk_{identity}_{side}",
        "orchestrator_decision_id": f"orchestrator_{identity}_{side}",
        "allocation_id": f"allocation_{identity}_{side}",
        "candidate_id": "challenger_v2_cuda_exitless_shared_model",
        "decision_id": "reused_multi_symbol_decision_batch",
        "symbol": "PEPEUSDT" if side == "long" else "ETHUSDT",
        "timeframe": "5m",
        "side": side,
        "allocated_margin_usd": 37.25,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }


@pytest.mark.parametrize("side", ["long", "short"])
@pytest.mark.parametrize(
    "shared_fields",
    [
        ("candidate_id",),
        ("decision_id",),
        ("candidate_id", "decision_id"),
    ],
)
def test_old_quarantine_reusing_model_candidate_or_batch_decision_retains_current_position(
    side: str,
    shared_fields: tuple[str, ...],
) -> None:
    current = _reused_candidate_position(side=side, identity="current")
    historical_quarantine = {
        "fill_id": "historical_fill",
        "prediction_id": "historical_prediction",
        "signal_id": "historical_signal",
        "intent_id": "historical_intent",
        "risk_decision_id": "historical_risk",
        "orchestrator_decision_id": "historical_orchestrator",
        "allocation_id": "historical_allocation",
        "accepted_fill_quarantined": True,
        "accepted_fill_quarantine_reasons": [
            "PERSISTED_ADMISSION_FINAL_CONTRACT_MISSING"
        ],
        "paper_only": True,
    }
    for field in shared_fields:
        historical_quarantine[field] = current[field]

    retained, removed = paper_loop._flag_invalid_admission_open_positions(  # noqa: SLF001
        [current],
        [historical_quarantine],
    )

    assert retained == [current]
    assert removed == []


@pytest.mark.parametrize("side", ["long", "short"])
@pytest.mark.parametrize("exact_identity", ["fill_id", "prediction_id"])
def test_exact_fill_or_prediction_quarantine_removes_only_exact_phantom(
    side: str,
    exact_identity: str,
) -> None:
    current = _reused_candidate_position(side=side, identity="current")
    phantom = _reused_candidate_position(side=side, identity="phantom")
    quarantine = {
        "fill_id": "historical_nonmatching_fill",
        "prediction_id": "historical_nonmatching_prediction",
        "candidate_id": current["candidate_id"],
        "decision_id": current["decision_id"],
        "accepted_fill_quarantined": True,
        "accepted_fill_quarantine_reasons": [
            "PERSISTED_ADMISSION_FINAL_CONTRACT_MISSING"
        ],
        "paper_only": True,
    }
    if exact_identity == "fill_id":
        quarantine["fill_id"] = phantom["entry_fill_id"]
    else:
        quarantine["prediction_id"] = phantom["prediction_id"]

    retained, removed = paper_loop._flag_invalid_admission_open_positions(  # noqa: SLF001
        [current, phantom],
        [quarantine],
    )

    assert retained == [current]
    assert len(removed) == 1
    assert removed[0]["position_id"] == phantom["position_id"]
    assert removed[0]["invalid_admission_open_position_removed"] is True
    assert removed[0]["accepted_fill_quarantined"] is True


@pytest.mark.parametrize("side", ["long", "short"])
def test_exact_quarantine_removal_is_single_release_without_wallet_or_close_effect(
    side: str,
) -> None:
    current = _reused_candidate_position(side=side, identity="current")
    phantom = _reused_candidate_position(side=side, identity="phantom")
    quarantine = {
        "fill_id": phantom["entry_fill_id"],
        "prediction_id": phantom["prediction_id"],
        "candidate_id": current["candidate_id"],
        "decision_id": current["decision_id"],
        "accepted_fill_quarantined": True,
        "accepted_fill_quarantine_reasons": [
            "PERSISTED_ADMISSION_FINAL_CONTRACT_MISSING"
        ],
        "paper_only": True,
    }
    retained, removed = paper_loop._flag_invalid_admission_open_positions(  # noqa: SLF001
        [current, phantom],
        [quarantine],
    )
    existing_close = {"close_id": "preexisting_close", "realized_net_pnl_usd": 4.0}
    base_receipt = {
        "schema_version": "paper_position_fill_reconciliation_v1",
        "status": "PASS",
        "input_position_count": 2,
        "accepted_fill_proof_count": 2,
        "retained_position_count": 2,
        "phantom_position_count": 0,
        "unresolved_position_count": 0,
        "phantom_positions": [],
        "unresolved_positions": [],
        "proof_bindings": [],
        "used_margin_released_usd": 0.0,
        "reserved_margin_released_usd": 0.0,
        "wallet_balance_mutation_usd": 0.0,
        "wallet_balance_usd": 1_000.0,
        "closed_trades": [existing_close],
        "rejection_reasons": [],
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }

    repaired = paper_loop._paper_reconciliation_with_invalid_admission_positions(  # noqa: SLF001
        base_receipt,
        [*removed, *removed],
        retained_positions=retained,
        active_proof_count=1,
        generated_utc="2026-07-28T08:00:00Z",
    )
    replay = paper_loop._paper_reconciliation_with_invalid_admission_positions(  # noqa: SLF001
        repaired,
        [],
        retained_positions=retained,
        active_proof_count=1,
        generated_utc="2026-07-28T08:01:00Z",
    )

    assert retained == [current]
    assert repaired["invalid_admission_positions_removed_count"] == 1
    assert repaired["retained_position_count"] == 1
    assert repaired["used_margin_released_usd"] == pytest.approx(37.25)
    assert repaired["reserved_margin_released_usd"] == 0.0
    assert repaired["wallet_balance_mutation_usd"] == 0.0
    assert repaired["wallet_balance_usd"] == 1_000.0
    assert repaired["closed_trades"] == [existing_close]
    assert repaired["counts_as_realized_paper_profit"] is False
    assert len(repaired["phantom_positions"]) == 1
    assert replay == repaired


@pytest.mark.parametrize("side", ["long", "short"])
def test_invalid_admission_position_reconciliation_is_symmetric_and_idempotent(
    side: str,
) -> None:
    proof, position = _open_position_fill_proof_fixture(side=side)
    source = paper_loop._paper_accepted_fill_proof_source(  # noqa: SLF001
        _FakeRedis(
            _open_position_fill_proof_store_payload([proof], positions=[position])
        )
    )
    ledger = {"open_positions": [position]}
    _, base = paper_loop._paper_reconcile_ledger_to_accepted_fill_proofs(  # noqa: SLF001
        ledger,
        source,
        generated_utc="2026-07-28T01:00:00Z",
    )
    quarantined = {
        **position,
        "accepted_fill_quarantined": True,
        "accepted_fill_quarantine_reasons": [
            "PERSISTED_ADMISSION_FINAL_CONTRACT_MISSING"
        ],
        "invalid_admission_open_position_removed": True,
    }

    repaired = paper_loop._paper_reconciliation_with_invalid_admission_positions(  # noqa: SLF001
        base,
        [quarantined, quarantined],
        retained_positions=[],
        active_proof_count=0,
        generated_utc="2026-07-28T01:01:00Z",
    )
    replay = paper_loop._paper_reconciliation_with_invalid_admission_positions(  # noqa: SLF001
        repaired,
        [],
        retained_positions=[],
        active_proof_count=0,
        generated_utc="2026-07-28T01:02:00Z",
    )

    assert repaired["status"] == "REPAIRED"
    assert repaired["invalid_admission_positions_removed_count"] == 1
    assert repaired["retained_position_count"] == 0
    assert repaired["accepted_fill_proof_count"] == 0
    assert repaired["used_margin_released_usd"] == pytest.approx(50.0)
    assert repaired["reserved_margin_released_usd"] == 0.0
    assert repaired["wallet_balance_mutation_usd"] == 0.0
    assert repaired["counts_as_realized_paper_profit"] is False
    assert repaired["idempotent"] is True
    assert replay == repaired


def test_post_lifecycle_reservation_status_clears_removed_position_margin() -> None:
    pre_lifecycle = {
        "schema_version": "paper_account_margin_v1",
        "status": "PASS",
        "open_position_count": 1,
        "used_margin": 48.515,
        "used_margin_usd": 48.515,
        "newly_reserved_margin": 0.0,
        "newly_reserved_margin_usd": 0.0,
        "free_margin": 2936.85,
        "free_margin_usd": 2936.85,
        "invariant_holds": True,
        "reserved_candidate_count": 0,
    }
    account = {
        "schema_version": "paper_account_margin_v1",
        "status": "PASS",
        "open_position_count": 0,
        "used_margin": 0.0,
        "used_margin_usd": 0.0,
        "free_margin": 2985.37,
        "free_margin_usd": 2985.37,
        "invariant_holds": True,
    }
    reconciliation = {
        "receipt_id": "a" * 64,
        "receipt_sha256": "b" * 64,
        "unresolved_position_count": 0,
    }

    status = paper_loop._paper_post_lifecycle_reservation_status(  # noqa: SLF001
        pre_lifecycle,
        account,
        reconciliation,
        generated_utc="2026-07-28T03:00:00Z",
    )

    assert status["status"] == "PASS"
    assert status["pre_lifecycle_used_margin_usd"] == pytest.approx(48.515)
    assert status["post_lifecycle_used_margin_usd"] == 0.0
    assert status["used_margin_usd"] == 0.0
    assert status["reserved_margin_usd"] == 0.0
    assert status["newly_reserved_margin_usd"] == 0.0
    assert status["open_position_count"] == 0
    assert status["free_margin_usd"] == pytest.approx(2985.37)
    assert status["final_reservation_reconciliation_valid"] is True
    assert status["post_lifecycle_reconciled"] is True


def test_priority_bucket_context_matches_strategy_regime_labels_for_paper_only_collection() -> None:
    readiness = {
        "generated_utc": "2026-06-23T20:55:00Z",
        "paper_only_label_collection_priority_buckets": [
            {
                "symbol": "HUSDT",
                "timeframe": "4h",
                "side": "long",
                "strategy": "trend_mode",
                "regime": "TREND",
                "confidence_bucket": "0.6-0.7",
                "closed_economic_outcome_count": 3,
                "sample_count_deficit_to_minimum": 27,
                "priority_reason": (
                    "PAPER_ONLY_COLLECT_MORE_B_GRADE_LABELS_FOR_PROMISING_UNDERPOWERED_BUCKET"
                ),
            }
        ],
    }
    priority_index = paper_loop._paper_only_label_collection_priority_index(readiness)  # noqa: SLF001
    intent = {
        "symbol": "HUSDT",
        "timeframe": "4h",
        "side": "long",
        "strategy_id": "trend_mode",
        "strategy_regime_labels": ["TREND"],
        "confidence_calibrated": 0.64,
    }
    allocation = {"model_inputs": {}}

    payload = paper_loop._attach_paper_only_label_collection_priority(  # noqa: SLF001
        intent=intent,
        allocation=allocation,
        priority_index=priority_index,
    )

    assert payload is not None
    assert intent["paper_only_label_collection_priority"] is True
    assert intent["paper_only_label_collection_priority_rank"] == 1
    assert intent["paper_only_label_collection_priority_bucket_key"] == (
        "HUSDT|4h|long|trend_mode|TREND|0.6-0.7"
    )
    assert intent["paper_only_label_collection_priority_sample_count_deficit_to_minimum"] == 27
    assert intent["counts_as_a_grade_evidence"] is False
    assert intent["a_grade_promotion_allowed"] is False
    assert intent["live_ready_implication"] is False
    assert allocation["model_inputs"]["paper_only_label_collection_priority"] is True


def test_priority_bucket_candidate_becomes_paper_only_b_grade_label_collection() -> None:
    intent = {
        "symbol": "HUSDT",
        "timeframe": "4h",
        "side": "long",
        "strategy_id": "trend_mode",
        "strategy_regime_labels": ["TREND"],
        "confidence_calibrated": 0.64,
        "expected_move_after_cost_bps": 8.0,
    }
    allocation = _allowed_allocation(
        confidence_calibrated=0.64,
        expected_move_after_cost_bps=8.0,
    )
    priority_index = paper_loop._paper_only_label_collection_priority_index(  # noqa: SLF001
        {
            "generated_utc": "2026-06-23T20:55:00Z",
            "paper_only_label_collection_priority_buckets": [
                {
                    "symbol": "HUSDT",
                    "timeframe": "4h",
                    "side": "long",
                    "strategy": "trend_mode",
                    "regime": "TREND",
                    "confidence_bucket": "0.6-0.7",
                    "closed_economic_outcome_count": 3,
                    "sample_count_deficit_to_minimum": 27,
                    "priority_reason": "PRIORITY_UNDERPOWERED_BUCKET",
                }
            ],
        }
    )
    paper_loop._attach_paper_only_label_collection_priority(  # noqa: SLF001
        intent=intent,
        allocation=allocation,
        priority_index=priority_index,
    )

    classification = paper_loop._classify_paper_opportunity_tier(  # noqa: SLF001
        signal={
            "selected_action": "long",
            "confidence_calibrated": 0.64,
            "expected_move_after_cost_bps": 8.0,
        },
        intent=intent,
        allocation=allocation,
        integrity_gate={"allowed": True},
        local_trade_gates_pass=False,
        exploration_trade_gates_pass=True,
        paper_fill_allowed_upstream=False,
        portfolio_drawdown_bps=100.0,
        preemptive_decision=_allow_preemptive_decision(),
    )

    assert classification["paper_opportunity_tier"] == "B_GRADE_EXPLORATION_PAPER"
    assert classification["paper_opportunity_tier_reason"] == (
        "PAPER_ONLY_PRIORITY_BUCKET_LABEL_COLLECTION"
    )
    assert classification["calibration_label_purpose"] == "B_GRADE_EXPLORATION_OUTCOME_LABEL"
    assert classification["paper_only_label_collection_priority"] is True
    assert (
        classification["paper_only_label_collection_priority_reason"]
        == "PRIORITY_UNDERPOWERED_BUCKET"
    )
    assert classification["counts_as_a_grade_evidence"] is False
    assert classification["a_grade_promotion_allowed"] is False
    assert classification["live_ready_implication"] is False
    assert classification["risk_budget_fraction_of_normal_adaptive"] > 0.0

    paper_loop._apply_paper_tier_classification(  # noqa: SLF001
        intent=intent,
        allocation=allocation,
        classification=classification,
    )

    assert allocation["paper_opportunity_tier_reason"] == (
        "PAPER_ONLY_PRIORITY_BUCKET_LABEL_COLLECTION"
    )
    assert allocation["model_inputs"]["paper_only_label_collection_priority"] is True
    assert allocation["model_inputs"]["a_grade_promotion_allowed"] is False
    assert allocation["model_inputs"]["live_ready_implication"] is False
    assert intent["source_tier"] == "B_GRADE_EXPLORATION_PAPER"
    assert intent["policy_tier"] == "B_GRADE_EXPLORATION_PAPER"
    assert intent["capital_class"] == "B_GRADE_EXPLORATION_FRACTIONAL_BUDGET"
    assert allocation["source_tier"] == "B_GRADE_EXPLORATION_PAPER"
    assert allocation["capital_class"] == "B_GRADE_EXPLORATION_FRACTIONAL_BUDGET"
    assert allocation["model_inputs"]["source_tier"] == "B_GRADE_EXPLORATION_PAPER"
    assert allocation["model_inputs"]["capital_class"] == ("B_GRADE_EXPLORATION_FRACTIONAL_BUDGET")


