class TestCgF044StateFileOverrideAndSyntheticQuarantine:
    """CG-F044: state file must never displace non-empty Redis close history,
    and close rows with no exit evidence must be quarantined, not counted."""

    _FIXTURE_STUB = {
        "trainer_feedback_id": "fb_incomplete",
        "outcome_label_id": "out_incomplete",
        "position_id": "pos_incomplete",
        "symbol": "BTCUSDT",
        "realized_pnl_bps": 4.2,
        "hold_time_seconds": 120,
        "exit_reason": "TIER_2_TAKE_PROFIT",
    }

    def _real_close(self, i: int) -> dict[str, object]:
        return {
            "close_id": f"close_{i}",
            "symbol": "ETHUSDT",
            "side": "long",
            "exit_price_utc": "2026-07-08T15:00:00Z",
            "realized_pnl_bps": 10.0 + i,
            "paper_session_id": "sess_a",
        }

    def test_state_file_does_not_override_non_empty_redis_closes(self, monkeypatch) -> None:
        redis_rows = [self._real_close(i) for i in range(18)]
        fake = _FakeRedis(
            {
                "v2:paper:closed_trades": redis_rows,
                "v2:paper:outcome_labels": [{"outcome_label_id": "lbl_1"}],
            }
        )
        monkeypatch.setattr(
            paper_loop,
            "_read_lifecycle_state_file",
            lambda *a, **kw: {
                "closed_trades": [dict(self._FIXTURE_STUB)],
                "closes": [dict(self._FIXTURE_STUB)],
                "outcome_labels": [],
            },
        )
        payload = paper_loop._read_existing_ledger_payload(fake)  # noqa: SLF001
        assert len(payload["closed_trades"]) == 18
        assert len(payload["closes"]) == 18
        assert payload["closed_trades"][0]["close_id"] == "close_0"
        assert len(payload["outcome_labels"]) == 1

    def test_state_file_still_rescues_when_redis_read_is_empty(self, monkeypatch) -> None:
        fake = _FakeRedis({})
        rescue_rows = [self._real_close(0)]
        monkeypatch.setattr(
            paper_loop,
            "_read_lifecycle_state_file",
            lambda *a, **kw: {"closed_trades": rescue_rows, "closes": rescue_rows},
        )
        payload = paper_loop._read_existing_ledger_payload(fake)  # noqa: SLF001
        assert len(payload["closed_trades"]) == 1
        assert payload["closed_trades"][0]["close_id"] == "close_0"

    def test_fixture_stub_without_exit_evidence_is_quarantined(self) -> None:
        real = self._real_close(1)
        restored_compact = {
            "symbol": "TLMUSDT",
            "side": "long",
            "realized_pnl_bps": 493.52,
            "reconstructed_from_artifacts": True,
        }
        kept, quarantined = paper_loop._split_closes_without_exit_evidence(  # noqa: SLF001
            [real, dict(self._FIXTURE_STUB), restored_compact]
        )
        assert real in kept
        assert restored_compact in kept
        assert len(quarantined) == 1
        assert quarantined[0]["position_id"] == "pos_incomplete"
        assert quarantined[0]["quarantine_reason"] == "NO_EXIT_EVIDENCE_SYNTHETIC_OR_TEST_ROW"
        assert quarantined[0]["counts_as_closed_trade"] is False

    def test_exit_time_alone_counts_as_exit_evidence(self) -> None:
        row = {
            "symbol": "SOLUSDT",
            "side": "short",
            "exit_time": "2026-07-08T15:05:00Z",
            "realized_pnl_bps": -3.0,
        }
        kept, quarantined = paper_loop._split_closes_without_exit_evidence(  # noqa: SLF001
            [row]
        )
        assert kept == [row]
        assert quarantined == []


# ---------------------------------------------------------------------------
# Policy-intent decision-record dereference (operator mission 2026-07-10):
# risk/orchestrator IDs on CUDA-policy signals must resolve into decision
# records (exact immutable Redis key; DENY wins). Previews and embedded values
# are observations only and never authorize a fill.
# ---------------------------------------------------------------------------


class _CanonicalRiskHandoffRedisStub:
    def __init__(
        self,
        exists_responses: list[int | Exception],
        records: dict[str, dict] | None = None,
    ) -> None:
        self._exists_responses = list(exists_responses)
        self._records = records or {}
        self.exists_calls: list[tuple[str, ...]] = []

    def exists(self, *keys: str) -> int:
        self.exists_calls.append(tuple(keys))
        index = min(len(self.exists_calls) - 1, len(self._exists_responses) - 1)
        response = self._exists_responses[index]
        if isinstance(response, Exception):
            raise response
        return response

    def get(self, key: str):
        value = self._records.get(key)
        return json.dumps(value) if value is not None else None


class _PublishingCanonicalRiskHandoffRedisStub(_CanonicalRiskHandoffRedisStub):
    def __init__(self, records_on_ready: dict[str, dict]) -> None:
        super().__init__([0, 1])
        self._records_on_ready = records_on_ready

    def exists(self, *keys: str) -> int:
        present = super().exists(*keys)
        if present:
            self._records.update(self._records_on_ready)
        return present


def _canonical_risk_handoff_clock() -> tuple[object, object]:
    state = {"now": 0.0}

    def monotonic() -> float:
        return state["now"]

    def sleep(seconds: float) -> None:
        state["now"] += seconds

    return monotonic, sleep


def test_canonical_risk_handoff_awaits_exact_frozen_ids_until_ready() -> None:
    signals = [
        {"signal_id": "sig_b", "risk_decision_id": "rd_b"},
        {"signal_id": "sig_a", "risk_decision_id": "rd_a"},
        {"signal_id": "sig_a_duplicate", "risk_decision_id": "rd_a"},
        {"signal_id": "sig_materialized", "risk_decision_id": "paper_risk_ignored"},
    ]
    original = deepcopy(signals)
    redis_client = _CanonicalRiskHandoffRedisStub([0, 2])
    monotonic, sleep = _canonical_risk_handoff_clock()

    status = paper_loop._paper_wait_for_canonical_risk_records(  # noqa: SLF001
        redis_client,
        signals,
        max_wait_seconds=1.0,
        poll_seconds=0.25,
        monotonic_clock=monotonic,
        sleep_fn=sleep,
    )

    expected_keys = (
        "v2:decision:risk:rd_a",
        "v2:decision:risk:rd_b",
    )
    assert redis_client.exists_calls == [expected_keys, expected_keys]
    assert status["status"] == "READY_ALL_CANONICAL_RISK_RECORDS_PRESENT"
    assert status["canonical_signal_row_count"] == 3
    assert status["canonical_risk_decision_id_count"] == 2
    assert status["records_present_initial"] == 0
    assert status["records_present_final"] == 2
    assert status["records_missing_final"] == 0
    assert status["all_records_present"] is True
    assert status["timed_out"] is False
    assert status["redis_read_error"] is False
    assert status["waited_seconds"] == pytest.approx(0.25)
    assert signals == original


def test_canonical_risk_handoff_never_awaits_synthetic_paper_risk_ids() -> None:
    signals = [
        {"signal_id": "sig_materialized", "risk_decision_id": "paper_risk_1"},
        {"signal_id": "sig_missing", "risk_decision_id": None},
    ]
    original = deepcopy(signals)
    redis_client = _CanonicalRiskHandoffRedisStub(
        [AssertionError("synthetic ID must not reach Redis EXISTS")]
    )

    status = paper_loop._paper_wait_for_canonical_risk_records(  # noqa: SLF001
        redis_client,
        signals,
    )

    assert redis_client.exists_calls == []
    assert status["status"] == "NOT_APPLICABLE_NO_CANONICAL_RISK_IDS"
    assert status["canonical_risk_decision_id_count"] == 0
    assert status["all_records_present"] is True
    assert status["waited_seconds"] == 0.0
    assert signals == original


def test_canonical_risk_handoff_redis_failure_is_fail_closed_and_read_only() -> None:
    signals = [{"signal_id": "sig_x", "risk_decision_id": "rd_x"}]
    original = deepcopy(signals)
    redis_client = _CanonicalRiskHandoffRedisStub([RuntimeError("redis unavailable")])
    monotonic, sleep = _canonical_risk_handoff_clock()

    status = paper_loop._paper_wait_for_canonical_risk_records(  # noqa: SLF001
        redis_client,
        signals,
        max_wait_seconds=1.0,
        poll_seconds=0.25,
        monotonic_clock=monotonic,
        sleep_fn=sleep,
    )

    assert status["status"] == "BLOCKED_REDIS_READ_ERROR"
    assert status["records_present_final"] == 0
    assert status["records_missing_final"] == 1
    assert status["all_records_present"] is False
    assert status["timed_out"] is False
    assert status["redis_read_error"] is True
    assert signals == original
    assert not {
        "risk_controller_decision",
        "risk_decision_record",
        "risk_allowed",
    } & set(status)


def test_canonical_risk_handoff_timeout_is_fail_closed_and_read_only() -> None:
    signals = [{"signal_id": "sig_x", "risk_decision_id": "rd_x"}]
    original = deepcopy(signals)
    redis_client = _CanonicalRiskHandoffRedisStub([0])
