def test_symbol_tf_closed_evidence_counts_feed_floor_input() -> None:
    # The dynamic floor's low_evidence_penalty reads symbol_timeframe_evidence_count
    # off the candidate row; the loop must populate it from real closed outcomes
    # (it was never written before, pinning the penalty at max forever).
    from v2.backend.app.cli import v2_trade_management_paper_loop as loop

    loop._set_symbol_tf_closed_evidence_counts(
        [
            {"symbol": "BTCUSDT", "timeframe": "1m"},
            {"symbol": "BTCUSDT", "timeframe": "1m"},
            {"symbol": "ETHUSDT", "timeframe": "5m"},
            {"symbol": "", "timeframe": "1m"},  # ignored: no symbol
        ]
    )
    assert loop._SYMBOL_TF_CLOSED_EVIDENCE_COUNTS[("BTCUSDT", "1m")] == 2
    assert loop._SYMBOL_TF_CLOSED_EVIDENCE_COUNTS[("ETHUSDT", "5m")] == 1
    assert ("", "1m") not in loop._SYMBOL_TF_CLOSED_EVIDENCE_COUNTS
    # Re-set replaces (per-cycle semantics).
    loop._set_symbol_tf_closed_evidence_counts([{"symbol": "SOLUSDT", "timeframe": "1h"}])
    assert ("BTCUSDT", "1m") not in loop._SYMBOL_TF_CLOSED_EVIDENCE_COUNTS


def test_probation_supervisor_freeze_keeps_bootstrap_exploration_alive() -> None:
    # Continue-with-feedback: a probation-supervisor halt must NOT kill the
    # bounded exploration/learning lane (the circuit-breaker bucket flags it
    # previously required only exist when a performance circuit is active).
    from app.cli.v2_trade_management_paper_loop import (
        _paper_risk_controller_exploration_can_override_entry_freeze,
    )

    freeze = {
        "paper_new_entries_halted": True,
        "reason": "PROBATION_SUPERVISOR_HALT:NEW_HIGH_CONFIDENCE_LOSS:FILUSDT,AVAXUSDT",
        "bootstrap_exploration_allowed": True,
    }
    intent = {
        "symbol": "BTCUSDT",
        "paper_opportunity_tier": "PAPER_RISK_CONTROLLER_EXPLORATION",
        "paper_only": True,
        "paper_risk_controller_exploration_eligible": True,
        "paper_exploration_paper_fill_allowed": True,
    }
    assert (
        _paper_risk_controller_exploration_can_override_entry_freeze(
            intent=intent, paper_entry_freeze=freeze
        )
        is True
    )

    # The symbol named in the freeze reason stays blocked.
    fil = {**intent, "symbol": "FILUSDT"}
    assert (
        _paper_risk_controller_exploration_can_override_entry_freeze(
            intent=fil, paper_entry_freeze=freeze
        )
        is False
    )

    # Truth-integrity freezes never carve out.
    truth_freeze = {
        "paper_new_entries_halted": True,
        "reason": "PORTFOLIO_TRUTH_UNTRUSTED",
    }
    assert (
        _paper_risk_controller_exploration_can_override_entry_freeze(
            intent=intent, paper_entry_freeze=truth_freeze
        )
        is False
    )

    # Non-probation freezes still require the circuit-breaker scoped flags.
    generic_freeze = {
        "paper_new_entries_halted": True,
        "reason": "PERFORMANCE_CIRCUIT_GLOBAL_HALT",
    }
    assert (
        _paper_risk_controller_exploration_can_override_entry_freeze(
            intent=intent, paper_entry_freeze=generic_freeze
        )
        is False
    )


def test_session_performance_sizing_factor_adapts_both_directions() -> None:
    # Operator-directed: sizing must adapt to realized live performance.
    from app.cli import v2_trade_management_paper_loop as loop

    def _rows(n, pnl_usd, notional=100.0):
        return [{"realized_net_pnl_usd": pnl_usd, "gross_notional_usd": notional} for _ in range(n)]

    # Below the minimum sample: neutral 1.0 regardless of results.
    loop._set_session_performance_sizing_evidence(_rows(3, 5.0))
    f = loop._session_performance_sizing_factor()
    assert f["session_performance_sizing_factor"] == 1.0
    assert "INSUFFICIENT_EVIDENCE" in f["session_performance_sizing_reason"]

    # Strong positive evidence (all wins) boosts, capped at 2.0.
    loop._set_session_performance_sizing_evidence(_rows(20, 5.0))
    f = loop._session_performance_sizing_factor()
    assert 1.0 < f["session_performance_sizing_factor"] <= 2.0

    # Deteriorating evidence (all losses) shrinks, floored at 0.5.
    loop._set_session_performance_sizing_evidence(_rows(20, -5.0))
    f = loop._session_performance_sizing_factor()
    assert 0.5 <= f["session_performance_sizing_factor"] < 1.0

    # Factor flows into the lane budget fraction, hard-capped at 1.0 of normal.
    loop._set_session_performance_sizing_evidence(_rows(20, 5.0))
    budget = loop._b_grade_exploration_budget_fraction(
        confidence_calibrated=0.74,
        drawdown_bps=0.0,
        expected_move_after_cost_bps=20.0,
        observed_spread_bps=2.0,
        expected_slippage_bps=2.0,
        fee_bps=4.0,
        depth_utilization_pct=10.0,
        long_short_ratio_status="V2_LONG_SHORT_RATIO_ATTACHED",
    )
    assert budget["session_performance_sizing_factor"] > 1.0
    assert 0.0 < budget["risk_budget_fraction_of_normal_adaptive"] <= 1.0
    # Reset to neutral for other tests.
    loop._set_session_performance_sizing_evidence([])


def test_portfolio_cascade_guard_decision_core() -> None:
    # Protect losers in confirmed cascades; let winners ride; close losers on
    # portfolio worst-case breach; do nothing otherwise.
    from app.cli.v2_portfolio_cascade_guard_loop import decide_directives

    positions = [
        {"symbol": "ALTAUSDT", "unrealized_pnl_bps": -25.0},
        {"symbol": "ALTBUSDT", "unrealized_pnl_bps": +80.0},
        {"symbol": "CALMUSDT", "unrealized_pnl_bps": -10.0},
    ]
    cascade = {
        "ALTAUSDT": {"status": "EVENT_CONFIRMED", "score": 0.9, "timeframe": "1m"},
        "ALTBUSDT": {"status": "EVENT_CONFIRMED", "score": 0.9, "timeframe": "1m"},
        "CALMUSDT": {"status": "ABSENT_NO_TRADE", "score": 0.1, "timeframe": "1m"},
    }
    d = {x["symbol"]: x for x in decide_directives(positions, cascade, {})}
    assert d["ALTAUSDT"]["action"] == "CLOSE"
    assert d["ALTBUSDT"]["action"] == "RIDE_TIGHTEN"  # winner rides the move
    assert "CALMUSDT" not in d

    breach = {"worst_case_liquidation_breached": True}
    d2 = {x["symbol"]: x for x in decide_directives(positions, cascade, breach)}
    assert d2["CALMUSDT"]["action"] == "CLOSE"  # portfolio breach closes losers
    assert d2["ALTBUSDT"]["action"] == "RIDE_TIGHTEN"


def _quarantine_row(
    *,
    symbol: str,
    pnl_bps: float,
    notional_usd: float,
    strategy: str = "microstructure_momentum",
    timeframe: str = "4h",
    confidence: float = 0.72,
) -> dict:
    return {
        "paper_only": True,
        "paper_opportunity_tier": "POSITIVE_EDGE_PROBATION_PAPER",
        "symbol": symbol,
        "timeframe": timeframe,
        "side": "long",
        "strategy_mode": strategy,
        "market_regime": "TREND",
        "confidence_calibrated": confidence,
        "realized_pnl_bps": pnl_bps,
        "realized_pnl_usd": pnl_bps / 10000.0 * notional_usd,
        "gross_notional_usd": notional_usd,
        "close_reason": "TIER_1_ATR_VOLATILITY_STOP" if pnl_bps <= 0 else "TIER_2_TRAILING_STOP",
        "exit_time": "2026-07-14T01:38:45Z",
    }


@pytest.fixture()
def _post_repair_epoch(monkeypatch):
    monkeypatch.setattr(
        paper_loop,
        "_paper_verified_exit_repair_deployed_utc",
        lambda: datetime(2026, 1, 1, tzinfo=timezone.utc),
    )


def test_single_thin_bucket_blocks_bucket_but_not_whole_book(_post_repair_epoch) -> None:
    """Regression (2026-07-14 deadlock): a 2-row bucket (one high-confidence
    loss sized larger than its win) quarantined AND escalated a global halt.
    The global freeze then blocked all new entries, so the bucket evidence
    could never grow and the halt re-derived forever — operator directive is
    bucket-scoped blocking with the book continuing. KITE-style diluting row
    uses a different strategy so only the thin strategy bucket blocks."""
    rows = [
        _quarantine_row(symbol="CRVUSDT", pnl_bps=66.8, notional_usd=12.0),
        _quarantine_row(symbol="FILUSDT", pnl_bps=-44.5, notional_usd=23.4),
        _quarantine_row(symbol="KITEUSDT", pnl_bps=370.4, notional_usd=24.0, strategy="trend_mode"),
    ]
    status = paper_loop._paper_bucket_quarantine_status(rows, generated_utc="2026-07-14T09:00:00Z")
    blocking = [b for b in status["quarantined_buckets"] if b.get("candidate_blocking")]
    assert blocking, "thin bucket must still candidate-block (no re-entry)"
    assert all(b.get("escalates_global_halt") is False for b in blocking)
    assert status["global_halt_required"] is False
    assert status["blocking_distinct_loss_row_count"] == 1


def test_material_bucket_still_escalates_global_halt(_post_repair_epoch) -> None:
    """A bucket at/above the material-sample floor with post-repair losses
    keeps the fail-closed global escalation."""
    rows = [
        _quarantine_row(symbol="AUSDT", pnl_bps=-30.0, notional_usd=20.0),
        _quarantine_row(symbol="BUSDT", pnl_bps=-25.0, notional_usd=20.0),
        _quarantine_row(symbol="CUSDT", pnl_bps=10.0, notional_usd=5.0),
        _quarantine_row(symbol="DUSDT", pnl_bps=-40.0, notional_usd=20.0),
    ]
    status = paper_loop._paper_bucket_quarantine_status(rows, generated_utc="2026-07-14T09:00:00Z")
    assert status["global_halt_required"] is True
    assert any(b.get("escalates_global_halt") for b in status["quarantined_buckets"])


def test_distinct_loss_breadth_escalates_across_thin_buckets(_post_repair_epoch) -> None:
    """Three distinct losing rows spread over thin buckets is systemic damage
    and must still halt the book, even though no single bucket reaches the
    material-sample floor. Uses 3 strategies x 2 rows (win smaller than loss)."""
    rows = []
    for i, strat in enumerate(("s_alpha", "s_beta", "s_gamma")):
        rows.append(
            _quarantine_row(symbol=f"W{i}USDT", pnl_bps=5.0, notional_usd=5.0, strategy=strat)
        )
        rows.append(
            _quarantine_row(symbol=f"L{i}USDT", pnl_bps=-60.0, notional_usd=25.0, strategy=strat)
        )
    status = paper_loop._paper_bucket_quarantine_status(rows, generated_utc="2026-07-14T09:00:00Z")
    assert status["blocking_distinct_loss_row_count"] >= 3
    assert status["global_halt_required"] is True


